export function monthLabel(key) {
  const names = ["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"];
  const [y, m] = String(key).split("-");
  const idx = Number(m) - 1;
  if (!names[idx] || !y) return key;
  return `${names[idx]} ${y.slice(2)}`;
}

